// ============================================================================
// dct8_ctrl.v -- distributed controller (four phase decoders)
// ----------------------------------------------------------------------------
// GENERATED by `python -m dct8 emit` from the exact modulo schedule
// (python/dct8/schedule.py).  Do not edit by hand: change the schedule and
// re-run the generator.
//
// Modulo schedule: period 8 (one sample per clock), CORDIC latency 2,
// output latency T0 = 15 (Y0 is read 15 clocks after x0 entered).
//
//   ph | BF0                | BF1                | CORDIC issue        | CORDIC done | out
//    0 | T1(L2,L3)          | T3(H2,H3)          | W3 k=3 (B1,A3)      | -           | Y1
//    1 | S0(x0,x1)          | U1(LH0,LH1)        | -                   | W3          | Y2
//    2 | U0(LL0,LL1)        | U3(HH0,HH1)        | -                   | -           | Y3
//    3 | S1(x2,x3)          | U2(HL0,HL1)        | V0 k=2 (Sp,D)       | -           | Y4
//    4 | T0(L0,L1)          | T2(H0,H1)          | V1 k=2 (SBp,DB)     | V0          | Y5
//    5 | S2(x4,x5)          | -                  | W2 k=2 (DBp,Dp)     | V1          | Y6
//    6 | -                  | -                  | W1 k=1 (B3,A1)      | W2          | Y7
//    7 | S3(x6,x7)          | -                  | -                   | W1          | Y0
// ============================================================================

// Butterfly datapath BF0: operand sources, SS-unit select, destinations.
module dct8_ctrl_bf0 (
    input  wire [2:0] phase,
    output reg        en,         // a butterfly executes this cycle
    output reg  [1:0] stage,      // flow-graph stage 1..3 (selects the SS unit flag)
    output reg        a_ib,       // operand A from the input buffer (else butterfly buffers)
    output reg        b_in,       // operand B is the incoming sample (else butterfly buffers)
    output reg  [2:0] a_addr,
    output reg  [2:0] b_addr,
    output reg  [1:0] sum_bank,   // 0 butterfly buffers, 1 memory bank, 2 output buffer
    output reg  [2:0] sum_addr,
    output reg  [1:0] diff_bank,
    output reg  [2:0] diff_addr
);
    always @(*) begin
        en = 1'b0; stage = 2'd1; a_ib = 1'b0; b_in = 1'b0; a_addr = 3'd0; b_addr = 3'd0;
        sum_bank = 2'd0; sum_addr = 3'd0; diff_bank = 2'd0; diff_addr = 3'd0;
        case (phase)
            3'd0: begin  // T1: (L2, L3) -> (LL1, LH1), stage 2
                en = 1'b1; stage = 2'd2; a_ib = 1'b0; b_in = 1'b0; a_addr = 3'd5; b_addr = 3'd7;
                sum_bank = 2'd0; sum_addr = 3'd7;  diff_bank = 2'd0; diff_addr = 3'd1;
            end
            3'd1: begin  // S0: (x0, x1) -> (L0, H0), stage 1
                en = 1'b1; stage = 2'd1; a_ib = 1'b1; b_in = 1'b1; a_addr = 3'd0; b_addr = 3'd0;
                sum_bank = 2'd0; sum_addr = 3'd1;  diff_bank = 2'd0; diff_addr = 3'd0;
            end
            3'd2: begin  // U0: (LL0, LL1) -> (Y0, D), stage 3
                en = 1'b1; stage = 2'd3; a_ib = 1'b0; b_in = 1'b0; a_addr = 3'd4; b_addr = 3'd7;
                sum_bank = 2'd2; sum_addr = 3'd0;  diff_bank = 2'd1; diff_addr = 3'd2;
            end
            3'd3: begin  // S1: (x2, x3) -> (L1, H1), stage 1
                en = 1'b1; stage = 2'd1; a_ib = 1'b1; b_in = 1'b1; a_addr = 3'd0; b_addr = 3'd0;
                sum_bank = 2'd0; sum_addr = 3'd3;  diff_bank = 2'd0; diff_addr = 3'd2;
            end
            3'd4: begin  // T0: (L0, L1) -> (LL0, LH0), stage 2
                en = 1'b1; stage = 2'd2; a_ib = 1'b0; b_in = 1'b0; a_addr = 3'd1; b_addr = 3'd3;
                sum_bank = 2'd0; sum_addr = 3'd4;  diff_bank = 2'd0; diff_addr = 3'd0;
            end
            3'd5: begin  // S2: (x4, x5) -> (L2, H2), stage 1
                en = 1'b1; stage = 2'd1; a_ib = 1'b1; b_in = 1'b1; a_addr = 3'd0; b_addr = 3'd0;
                sum_bank = 2'd0; sum_addr = 3'd5;  diff_bank = 2'd0; diff_addr = 3'd1;
            end
            3'd6: ; // idle
            3'd7: begin  // S3: (x6, x7) -> (L3, H3), stage 1
                en = 1'b1; stage = 2'd1; a_ib = 1'b1; b_in = 1'b1; a_addr = 3'd0; b_addr = 3'd0;
                sum_bank = 2'd0; sum_addr = 3'd7;  diff_bank = 2'd0; diff_addr = 3'd6;
            end
            default: ;
        endcase
    end
endmodule

// Butterfly datapath BF1: operand sources, SS-unit select, destinations.
module dct8_ctrl_bf1 (
    input  wire [2:0] phase,
    output reg        en,         // a butterfly executes this cycle
    output reg  [1:0] stage,      // flow-graph stage 1..3 (selects the SS unit flag)
    output reg  [2:0] a_addr,
    output reg  [2:0] b_addr,
    output reg  [1:0] sum_bank,   // 0 butterfly buffers, 1 memory bank, 2 output buffer
    output reg  [2:0] sum_addr,
    output reg  [1:0] diff_bank,
    output reg  [2:0] diff_addr
);
    always @(*) begin
        en = 1'b0; stage = 2'd1; a_addr = 3'd0; b_addr = 3'd0;
        sum_bank = 2'd0; sum_addr = 3'd0; diff_bank = 2'd0; diff_addr = 3'd0;
        case (phase)
            3'd0: begin  // T3: (H2, H3) -> (HH1, HL1), stage 2
                en = 1'b1; stage = 2'd2; a_addr = 3'd1; b_addr = 3'd6;
                sum_bank = 2'd0; sum_addr = 3'd5;  diff_bank = 2'd0; diff_addr = 3'd6;
            end
            3'd1: begin  // U1: (LH0, LH1) -> (Sp, Dp), stage 3
                en = 1'b1; stage = 2'd3; a_addr = 3'd0; b_addr = 3'd1;
                sum_bank = 2'd1; sum_addr = 3'd1;  diff_bank = 2'd1; diff_addr = 3'd0;
            end
            3'd2: begin  // U3: (HH0, HH1) -> (SBp, DBp), stage 3
                en = 1'b1; stage = 2'd3; a_addr = 3'd2; b_addr = 3'd5;
                sum_bank = 2'd1; sum_addr = 3'd4;  diff_bank = 2'd1; diff_addr = 3'd3;
            end
            3'd3: begin  // U2: (HL0, HL1) -> (Y4, DB), stage 3
                en = 1'b1; stage = 2'd3; a_addr = 3'd3; b_addr = 3'd6;
                sum_bank = 2'd2; sum_addr = 3'd1;  diff_bank = 2'd1; diff_addr = 3'd1;
            end
            3'd4: begin  // T2: (H0, H1) -> (HH0, HL0), stage 2
                en = 1'b1; stage = 2'd2; a_addr = 3'd0; b_addr = 3'd2;
                sum_bank = 2'd0; sum_addr = 3'd2;  diff_bank = 2'd0; diff_addr = 3'd3;
            end
            3'd5: ; // idle
            3'd6: ; // idle
            3'd7: ; // idle
            default: ;
        endcase
    end
endmodule

// Central CORDIC unit: issue (stage A) and completion (stage B, one clock later).
module dct8_ctrl_mr (
    input  wire [2:0] phase,
    output reg        issue,      // a rotation enters stage A
    output reg  [1:0] k,          // angle: k*pi/16, k = 1..3
    output reg  [2:0] a_addr,     // memory-bank addresses of the operands
    output reg  [2:0] b_addr,
    output reg        done,       // stage B writes a result pair
    output reg        dst_ob,     // 1: output buffer, 0: memory bank
    output reg  [2:0] u_addr,
    output reg  [2:0] v_addr
);
    always @(*) begin
        issue = 1'b0; k = 2'd1; a_addr = 3'd0; b_addr = 3'd0;
        done = 1'b0; dst_ob = 1'b0; u_addr = 3'd0; v_addr = 3'd0;
        case (phase)
            3'd0: begin
                issue = 1'b1; k = 2'd3; a_addr = 3'd0; b_addr = 3'd2;  // W3: rotate (B1, A3) by 3*pi/16
            end
            3'd1: begin
                done = 1'b1; dst_ob = 1'b1; u_addr = 3'd2; v_addr = 3'd0;  // W3 -> (Y5, Y3)
            end
            3'd2: begin
                ; // idle
            end
            3'd3: begin
                issue = 1'b1; k = 2'd2; a_addr = 3'd1; b_addr = 3'd2;  // V0: rotate (Sp, D) by 2*pi/16
            end
            3'd4: begin
                issue = 1'b1; k = 2'd2; a_addr = 3'd4; b_addr = 3'd1;  // V1: rotate (SBp, DB) by 2*pi/16
                done = 1'b1; dst_ob = 1'b0; u_addr = 3'd2; v_addr = 3'd1;  // V0 -> (A3, A1)
            end
            3'd5: begin
                issue = 1'b1; k = 2'd2; a_addr = 3'd3; b_addr = 3'd0;  // W2: rotate (DBp, Dp) by 2*pi/16
                done = 1'b1; dst_ob = 1'b0; u_addr = 3'd3; v_addr = 3'd0;  // V1 -> (B3, B1)
            end
            3'd6: begin
                issue = 1'b1; k = 2'd1; a_addr = 3'd3; b_addr = 3'd1;  // W1: rotate (B3, A1) by 1*pi/16
                done = 1'b1; dst_ob = 1'b1; u_addr = 3'd3; v_addr = 3'd2;  // W2 -> (Y6, Y2)
            end
            3'd7: begin
                done = 1'b1; dst_ob = 1'b1; u_addr = 3'd4; v_addr = 3'd0;  // W1 -> (Y7, Y1)
            end
            default: ;
        endcase
    end
endmodule

// Input buffer and rearrange (output) unit: in-order read-out of Y0..Y7.
module dct8_ctrl_io (
    input  wire [2:0] phase,
    output reg        ib_we,
    output reg  [2:0] ob_raddr,
    output reg  [2:0] out_k,      // index of the coefficient read this cycle
    output wire       out_start   // Y0 of a block is read this cycle
);
    assign out_start = (phase == 3'd7);
    always @(*) begin
        ib_we = 1'b0; ob_raddr = 3'd0; out_k = 3'd0;
        case (phase)
            3'd0: begin
                ib_we = 1'b1;  // x0 waits one clock for its partner
                ob_raddr = 3'd0; out_k = 3'd1;  // read Y1
            end
            3'd1: begin
                ib_we = 1'b0;
                ob_raddr = 3'd2; out_k = 3'd2;  // read Y2
            end
            3'd2: begin
                ib_we = 1'b1;  // x2 waits one clock for its partner
                ob_raddr = 3'd0; out_k = 3'd3;  // read Y3
            end
            3'd3: begin
                ib_we = 1'b0;
                ob_raddr = 3'd1; out_k = 3'd4;  // read Y4
            end
            3'd4: begin
                ib_we = 1'b1;  // x4 waits one clock for its partner
                ob_raddr = 3'd2; out_k = 3'd5;  // read Y5
            end
            3'd5: begin
                ib_we = 1'b0;
                ob_raddr = 3'd3; out_k = 3'd6;  // read Y6
            end
            3'd6: begin
                ib_we = 1'b1;  // x6 waits one clock for its partner
                ob_raddr = 3'd4; out_k = 3'd7;  // read Y7
            end
            3'd7: begin
                ib_we = 1'b0;
                ob_raddr = 3'd0; out_k = 3'd0;  // read Y0
            end
            default: ;
        endcase
    end
endmodule
